package net.townymap.vote;
import net.townymap.*;import net.townymap.api.EarthMcApiClient;import net.townymap.model.VotePartyStatus;import java.util.concurrent.atomic.AtomicBoolean;
public final class VotePartyService{private static final long REFRESH=60_000,RETRY=15_000;private final EarthMcApiClient api;private final TownyMapConfig config;private final AtomicBoolean loading=new AtomicBoolean();private volatile VotePartyStatus status;private volatile long lastAttempt;public VotePartyService(EarthMcApiClient a,TownyMapConfig c){api=a;config=c;}public void tick(){if(!config.votePartyEnabled)return;long now=System.currentTimeMillis(),delay=status==null?RETRY:REFRESH;if(now-lastAttempt<delay||!loading.compareAndSet(false,true))return;lastAttempt=now;api.fetchVoteParty().whenComplete((next,error)->{if(next!=null)status=next;loading.set(false);});}public VotePartyStatus status(){tick();return status;}public boolean loading(){return loading.get();}}
